function drainPlan(rains: number[]): number[] {
  const n = rains.length;
  // nxt[i] leads to the first unused dry day at or after i (n = none)
  const nxt = new Array(n + 1);
  for (let i = 0; i <= n; i++) nxt[i] = i < n && rains[i] !== 0 ? i + 1 : i;
  const find = (i: number): number => {
    let root = i;
    while (nxt[root] !== root) root = nxt[root];
    while (nxt[i] !== root) { const up = nxt[i]; nxt[i] = root; i = up; }
    return root;
  };
  const plan = new Array(n).fill(-1);
  const filledOn = new Map<number, number>();
  for (let i = 0; i < n; i++) {
    const lake = rains[i];
    if (lake === 0) { plan[i] = 1; continue; }
    if (filledOn.has(lake)) {
      const d = find(filledOn.get(lake)! + 1);
      if (d > i) return [];
      plan[d] = lake;
      nxt[d] = d + 1;
    }
    filledOn.set(lake, i);
  }
  return plan;
}

