            root = i
            while nxt[root] != root:
                root = nxt[root]
            while nxt[i] != root:
                nxt[i], i = root, nxt[i]
            return root

        plan = [-1 if r else 1 for r in rains]
        filled_on = {}
        for i, lake in enumerate(rains):
            if not lake:
                continue
            if lake in filled_on:
                d = find(filled_on[lake] + 1)
                if d > i:
                    return []
                plan[d] = lake
                nxt[d] = d + 1
            filled_on[lake] = i
        return plan

